from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Auto_stats(EmssimCommand):
    def __init__(self, method='auto_stats', timeout=60, rpc_connection_name='localRPC'):
        super(Auto_stats, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Auto_stats, self).on_new_data(**data)
        if 'msg' in data:
            if data['msg'] == 'Automatic PM Stats upload and parse is INACTIVE':
                self._ret['information'] = {}
                self._ret['information']['msg'] = data['msg']
                self._ret['information']['next_run_after'] = -1
        if 'info' in data:
            if 'information' not in self._ret:
                self._ret['information'] = {}
            self._ret['information'] = data['info']
